face-container-high hover:text-on-surface transition-all" data-path="laporan-dan-rekap-xp" href="#"><span class="material-symbols-outlined text-[20px]">analytics</span><span class="font-label-lg text-label-lg">Laporan &amp; Rekap XP</span></a><a class="flex items-center gap-space-sm px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface transition-all" data-path="pengaturan-verifikator" href="#"><span class="material-symbols-outlined text-[20px]">tune</span><span class="font-label-lg text-label-lg">Pengaturan Verifikator</span></a><a class="flex items-center gap-space-sm px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface transition-all" href="/dashboard"><span class="material-symbols-outlined text-[20px]">grid_view</span><span class="font-label-lg text-label-lg">Ke Portal Mahasiswa</span></a><a class="flex items-center gap-space-sm px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-error-container/50 hover:text-error transition-all" href="/login"><span class="material-symbols-outlined text-[20px]">logout</span><span class="font-label-lg text-label-lg">Keluar / SSO</span></a></nav></div><div class="p-space-sm rounded-xl bg-surface-container-lowest shadow-[0_2px_6px_-1px_rgba(0,0,0,0.02)] flex items-center gap-space-xs"><span class="material-symbols-outlined text-[18px] text-badge-violet">lock_clock</span><span class="font-label-sm text-label-sm text-on-surface-variant">Mode Verifikator Kampus • Semester Ganjil 24/25</span></div></aside><div class="pl-72"><header class="fixed top-0 left-72 right-0 h-16 bg-surface/80 backdrop-blur-xl shadow-[0_1px_8px_rgba(0,0,0,0.04)] z-40 px-gutter flex items-center justify-between gap-space-md"><div class="flex items-center gap-space-md"><span class="px-space-sm py-1 rounded-full bg-pastel-lavender-start text-badge-violet font-label-md text-label-md font-semibold">Portal Verifikator Kampus</span><div class="relative flex items-center w-80"><span class="material-symbols-outlined absolute left-3 text-on-surface-variant text-[18px]">search</span><input class="w-full pl-9 pr-space-md py-1.5 bg-surface-card rounded-full font-body-sm text-body-sm text-on-surface placeholder:text-on-surface-variant focus:outline-none focus:ring-2 focus:ring-primary shadow-[0_2px_6px_-1px_rgba(0,0,0,0.02)]" placeholder="Cari Mahasiswa, NIM, atau No. SK..." type="text"></div></div><div class="flex items-center gap-space-md"><button class="relative p-2 rounded-full hover:bg-surface-container hover:text-on-surface text-on-surface-variant transition-colors flex items-center justify-center"><span class="material-symbols-outlined text-[22px]">notifications</span><span class="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-error rounded-full ring-2 ring-surface"></span></button><div class="flex items-center gap-space-sm pl-space-sm"><div class="flex flex-col text-right"><span class="font-label-lg text-label-lg text-on-surface font-semibold">Dr. Hendra Wijaya, M.Kom.</span><span class="font-body-sm text-body-sm text-on-surface-variant">BAAK / Verifikator Akademik</span></div><div class="w-8 h-8 rounded-full bg-primary flex items-center justify-center"><span class="material-symbols-outlined text-on-primary text-[18px]">person</span></div></div></div></header><main class="relative pt-16 w-full px-gutter bg-background"><div class="flex flex-col w-full pb-space-2xl">
<!-- Header Section with Actions -->
<header class="flex flex-col lg:flex-row lg:items-center justify-between gap-space-md mb-space-xl">
<div class="flex flex-col gap-1 max-w-2xl">
<div class="flex items-center gap-space-xs">
<span class="inline-flex items-center px-2.5 py-0.5 rounded-full bg-pastel-lavender-start text-badge-violet font-label-sm text-label-sm">
          PIC: Nayla • Epic 1
        </span>
<span class="inline-flex items-center px-2.5 py-0.5 rounded-full bg-surface-container text-on-surface-variant font-label-sm text-label-sm">
          SLA Evaluasi: &lt; 24 Jam
        </span>
</div>
<h1 class="font-headline-lg text-headline-lg text-on-surface font-bold tracking-tight">
        Dashboard Validasi &amp; Persetujuan Misi
      </h1>
<p class="font-body-md text-body-md text-text-muted leading-relaxed">
        Kelola dan verifikasi berkas bukti capaian kegiatan mahasiswa untuk mendistribusikan poin XP dan memperbarui e-transkrip portofolio resmi kampus.
      </p>
</div>
<!-- Action Toolbar -->
<div class="flex flex-wrap items-center gap-space-sm self-start lg:self-center">
<!-- Periode Dropdown -->
<div class="relative inline-block text-left">
<button class="inline-flex items-center justify-between gap-space-xs px-space-md py-2 bg-surface-card rounded-full shadow-sm text-on-surface font-label-md text-label-md hover:bg-surface-container-low transition-all" id="periodSelectorBtn" type="button">
<span class="material-symbols-outlined text-[18px] text-badge-violet">calendar_month</span>
<span id="currentPeriodText" class="">Semester Ganjil 2024/2025</span>
<span class="material-symbols-outlined text-[18px] text-outline">expand_more</span>
</button>
<div class="hidden absolute right-0 mt-2 w-56 rounded-xl bg-surface-card shadow-xl p-1 z-30" id="periodDropdownMenu">
<button class="w-full text-left px-space-md py-2 rounded-lg font-body-sm text-body-sm text-on-surface hover:bg-pastel-lavender-start hover:text-badge-violet" onclick="selectPeriod('Semester Ganjil 2024/2025')">Semester Ganjil 2024/2025</button>
<button class="w-full text-left px-space-md py-2 rounded-lg font-body-sm text-body-sm text-on-surface hover:bg-pastel-lavender-start hover:text-badge-violet" onclick="selectPeriod('Semester Genap 2023/2024')">Semester Genap 2023/2024</button>
<button class="w-full text-left px-space-md py-2 rounded-lg font-body-sm text-body-sm text-on-surface hover:bg-pastel-lavender-start hover:text-badge-violet" onclick="selectPeriod('Program MBKM Batch 6')">Program MBKM Batch 6</button>
</div>
</div>
<!-- Export Rekap -->
<button class="inline-flex items-center gap-space-xs px-space-md py-2 bg-surface-card rounded-full shadow-sm text-on-surface font-label-md text-label-md hover:bg-surface-container-low hover:text-primary transition-all" onclick="triggerToast('Menyiapkan file ekspor XLS &amp; PDF riwayat persetujuan...')">
<span class="material-symbols-outlined text-[18px] text-badge-sky">download</span>
        Export Rekap Validasi
      </button>
<!-- Tambah Quest Baru -->
<button class="inline-flex items-center gap-space-xs px-space-lg py-2 rounded-full bg-gradient-to-r from-primary-container to-secondary text-on-primary font-label-md text-label-md shadow-[0_4px_14px_rgba(108,92,231,0.3)] hover:opacity-95 hover:shadow-md transition-all" onclick="openNewQuestModal()">
<span class="material-symbols-outlined text-[18px]">add_circle</span>
        + Tambah Quest Baru
      </button>
</div>
</header>
<!-- Key Metrics Row (4 Cards) -->
<section class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-space-md mb-space-xl">
<!-- Card 1: Menunggu Validasi -->
<div class="relative p-space-md rounded-2xl bg-surface-card shadow-[0_4px_20px_-2px_rgba(108,92,231,0.04),0_2px_6px_-1px_rgba(0,0,0,0.02)] flex flex-col justify-between overflow-hidden group hover:-translate-y-0.5 transition-all">
<div class="flex items-start justify-between">
<div>
<span class="font-label-md text-label-md text-text-muted">Menunggu Validasi</span>
<div class="flex items-baseline gap-space-xs mt-1">
<h3 class="font-headline-xl text-headline-xl text-on-surface font-bold">18</h3>
<span class="font-label-sm text-label-sm text-text-muted">Pengajuan</span>
</div>
</div>
<div class="w-10 h-10 rounded-full bg-badge-gold/15 flex items-center justify-center text-badge-gold">
<span class="material-symbols-outlined text-[22px]">hourglass_top</span>
</div>
</div>
<div class="flex items-center justify-between mt-space-md pt-space-xs">
<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-badge-gold/20 text-on-surface font-label-sm text-label-sm font-semibold">
<span class="w-1.5 h-1.5 rounded-full bg-badge-gold"></span> +5 Baru Hari Ini
        </span>
<span class="font-label-sm text-label-sm text-text-muted">Prioritas Tinggi: 4</span>
</div>
<div class="absolute bottom-0 left-0 right-0 h-1 bg-badge-gold/40"></div>
</div>
<!-- Card 2: Disetujui Hari Ini -->
<div class="relative p-space-md rounded-2xl bg-surface-card shadow-[0_4px_20px_-2px_rgba(108,92,231,0.04),0_2px_6px_-1px_rgba(0,0,0,0.02)] flex flex-col justify-between overflow-hidden group hover:-translate-y-0.5 transition-all">
<div class="flex items-start justify-between">
<div>
<span class="font-label-md text-label-md text-text-muted">Disetujui Hari Ini</span>
<div class="flex items-baseline gap-space-xs mt-1">
<h3 class="font-headline-xl text-headline-xl text-on-surface font-bold">34</h3>
<span class="font-label-sm text-label-sm text-text-muted">Mahasiswa</span>
</div>
</div>
<div class="w-10 h-10 rounded-full bg-badge-emerald/15 flex items-center justify-center text-badge-emerald">
<span class="material-symbols-outlined text-[22px]">verified_user</span>
</div>
</div>
<div class="flex items-center justify-between mt-space-md pt-space-xs">
<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-badge-emerald/15 text-badge-emerald font-label-sm text-label-sm font-semibold">
<span class="material-symbols-outlined text-[14px]">bolt</span> +12,450 XP Terdistribusi
        </span>
<span class="font-label-sm text-label-sm text-badge-emerald">Tercatat di BAAK</span>
</div>
<div class="absolute bottom-0 left-0 right-0 h-1 bg-badge-emerald"></div>
</div>
<!-- Card 3: Perlu Revisi / Ditolak -->
<div class="relative p-space-md rounded-2xl bg-surface-card shadow-[0_4px_20px_-2px_rgba(108,92,231,0.04),0_2px_6px_-1px_rgba(0,0,0,0.02)] flex flex-col justify-between overflow-hidden group hover:-translate-y-0.5 transition-all">
<div class="flex items-start justify-between">
<div>
<span class="font-label-md text-label-md text-text-muted">Perlu Revisi / Ditolak</span>
<div class="flex items-baseline gap-space-xs mt-1">
<h3 class="font-headline-xl text-headline-xl text-error font-bold">3</h3>
