</div>
</div>
<div class="w-10 h-10 rounded-full bg-error-container flex items-center justify-center text-error">
<span class="material-symbols-outlined text-[22px]">assignment_late</span>
</div>
</div>
<div class="flex items-center justify-between mt-space-md pt-space-xs">
<span class="inline-flex items-center px-2 py-0.5 rounded-full bg-error-container text-on-error-container font-label-sm text-label-sm font-semibold">
          Berkas Buram / No SK Ganda
        </span>
<span class="font-label-sm text-label-sm text-text-muted">Menunggu Resubmit</span>
</div>
<div class="absolute bottom-0 left-0 right-0 h-1 bg-error"></div>
</div>
<!-- Card 4: SLA Waktu Verifikasi -->
<div class="relative p-space-md rounded-2xl bg-surface-card shadow-[0_4px_20px_-2px_rgba(108,92,231,0.04),0_2px_6px_-1px_rgba(0,0,0,0.02)] flex flex-col justify-between overflow-hidden group hover:-translate-y-0.5 transition-all">
<div class="flex items-start justify-between">
<div>
<span class="font-label-md text-label-md text-text-muted">Rata-rata Respon Verifikasi</span>
<div class="flex items-baseline gap-space-xs mt-1">
<h3 class="font-headline-xl text-headline-xl text-badge-violet font-bold">4.2</h3>
<span class="font-label-sm text-label-sm text-text-muted">Jam / Kasus</span>
</div>
</div>
<div class="w-10 h-10 rounded-full bg-pastel-lavender-start flex items-center justify-center text-badge-violet">
<span class="material-symbols-outlined text-[22px]">speed</span>
</div>
</div>
<div class="flex items-center justify-between mt-space-md pt-space-xs">
<span class="inline-flex items-center gap-1 font-label-sm text-label-sm text-text-muted">
