        </span>
<span class="inline-flex items-center px-2 py-0.5 rounded-full bg-badge-emerald/15 text-badge-emerald font-label-sm text-label-sm font-bold">
          98.2% On-time
        </span>
</div>
<div class="absolute bottom-0 left-0 right-0 h-1 bg-badge-violet"></div>
</div>
</section>
<!-- Main Content Layout (Table + Embedded Review Sandbox Panel) -->
<div class="grid grid-cols-1 xl:grid-cols-12 gap-space-lg items-start">
<!-- Left / Center: Validation Queue Table (8 cols on xl) -->
<div class="xl:col-span-8 flex flex-col gap-space-md">
<!-- Filter Bar & Quick Search Card -->
<div class="p-space-md rounded-2xl bg-surface-card shadow-[0_4px_20px_-2px_rgba(108,92,231,0.04),0_2px_6px_-1px_rgba(0,0,0,0.02)] flex flex-col gap-space-md">
<!-- Tabs & Status Row -->
<div class="flex flex-wrap items-center justify-between gap-space-sm pb-space-sm">
<div class="flex items-center gap-space-xs bg-surface-container-low p-1 rounded-full">
<button class="tab-btn px-space-md py-1.5 rounded-full bg-surface-card text-on-surface font-label-sm text-label-sm shadow-sm font-bold transition-all" id="tab-pending" onclick="filterByTab('pending')">
