            </button>
<button class="tab-btn px-space-md py-1.5 rounded-full text-on-surface-variant hover:text-on-surface font-label-sm text-label-sm transition-all" id="tab-rejected" onclick="filterByTab('rejected')">
              Ditolak / Revisi (9)
            </button>
</div>
<div class="flex items-center gap-space-xs">
<span class="font-label-sm text-label-sm text-text-muted">Urutkan:</span>
<select class="bg-surface-container-low text-on-surface font-label-sm text-label-sm rounded-full px-3 py-1 focus:outline-none cursor-pointer" id="sortSelect" onchange="sortQueue(this.value)">
<option value="newest">Terbaru Masuk</option>
<option value="highest-xp">XP Tertinggi</option>
<option value="oldest">Antrean Terlama</option>
</select>
</div>
</div>
<!-- Search Input -->
<div class="relative w-full">
<span class="material-symbols-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-on-surface-variant text-[20px]">manage_search</span>
<input class="w-full pl-11 pr-space-md py-2.5 bg-surface-container-lowest rounded-xl font-body-sm text-body-sm text-on-surface placeholder:text-text-muted focus:outline-none focus:ring-2 focus:ring-primary shadow-sm" id="queueSearchInput" onkeyup="handleQuickSearch(this.value)" placeholder="Cari nama mahasiswa, NIM, judul quest, atau nomor SK..." type="text">
<button class="hidden absolute right-3 top-1/2 -translate-y-1/2 text-text-muted hover:text-on-surface" id="clearSearchBtn" onclick="clearSearch()">
<span class="material-symbols-outlined text-[18px]">cancel</span>
</button>
</div>
<!-- Category Filter Pills -->
<div class="flex items-center gap-space-xs overflow-x-auto pb-1 scrollbar-none">
<button class="cat-pill px-3 py-1 rounded-full bg-pastel-lavender-start text-badge-violet font-label-sm text-label-sm whitespace-nowrap font-bold transition-all" onclick="filterCategory('all', this)">
            Semua (18)
          </button>
<button class="cat-pill px-3 py-1 rounded-full bg-surface-container text-on-surface-variant hover:bg-pastel-lavender-start hover:text-badge-violet font-label-sm text-label-sm whitespace-nowrap transition-all" onclick="filterCategory('Akademik &amp; Riset', this)">
            Akademik &amp; Riset (6)
          </button>
<button class="cat-pill px-3 py-1 rounded-full bg-surface-container text-on-surface-variant hover:bg-pastel-lavender-start hover:text-badge-violet font-label-sm text-label-sm whitespace-nowrap transition-all" onclick="filterCategory('Kepanitiaan &amp; Organisasi', this)">
