      document.getElementById('currentPeriodText').innerText = period;
      document.getElementById('periodDropdownMenu').classList.add('hidden');
      triggerToast('Filter periode diubah ke: ' + period);
    }

    document.getElementById('periodSelectorBtn').addEventListener('click', function(e) {
      e.stopPropagation();
      const menu = document.getElementById('periodDropdownMenu');
      menu.classList.toggle('hidden');
    });

    document.addEventListener('click', function() {
      const menu = document.getElementById('periodDropdownMenu');
      if (menu && !menu.classList.contains('hidden')) {
        menu.classList.add('hidden');
      }
    });

    function loadReviewInspector(id) {
      activeInspectedId = id;
      const data = mockData[id];
      if (!data) return;

      document.getElementById('sandboxStudentName').innerText = data.name;
      document.getElementById('sandboxStudentNim').innerText = 'NIM ' + data.nim + ' • ' + data.study;
      document.getElementById('sandboxQuestTitle').innerText = data.quest;
      document.getElementById('sandboxRewardPill').innerText = '+' + data.reward + ' XP';
      document.getElementById('sandboxFileName').innerText = data.file;
      document.getElementById('modalDocTitle').innerText = data.file;
      document.getElementById('sandboxApproveText').innerText = 'Setujui & Tambah +' + data.reward + ' XP';

      // Highlight target card softly
      document.querySelectorAll('.queue-card').forEach(c => c.classList.remove('ring-2', 'ring-primary'));
      const activeCard = document.getElementById('row-item-' + id);
      if (activeCard) {
        activeCard.classList.add('ring-2', 'ring-primary');
      }
      triggerToast('Memuat berkas untuk ' + data.name);
    }

    function approveDirect(id, name, xp) {
      const card = document.getElementById('row-item-' + id);
      if (card) {
        card.style.opacity = '0.4';
        card.style.transform = 'scale(0.98)';
        setTimeout(() => {
          card.remove();
          triggerToast('Pengajuan ' + name + ' disetujui! (+' + xp + ' XP didistribusikan)');
        }, 300);
      }
    }

    function rejectDirect(id, name) {
      const reason = prompt('Masukkan alasan penolakan/revisi untuk ' + name + ':', 'Berkas bukti sertifikat buram atau tanda tangan tidak terlihat jelas.');
      if (reason) {
        const card = document.getElementById('row-item-' + id);
        if (card) {
          card.style.opacity = '0.4';
          setTimeout(() => {
            card.remove();
            triggerToast('Pengajuan ' + name + ' dikembalikan untuk revisi.', false);
          }, 300);
        }
      }
    }

    function submitSandboxDecision(action) {
      const data = mockData[activeInspectedId];
      const studentName = data ? data.name : 'Mahasiswa';
      const xp = data ? data.reward : 500;
      const notes = document.getElementById('verifierNotes').value;

      if (action === 'approve') {
        approveDirect(activeInspectedId, studentName, xp);
      } else {
        const card = document.getElementById('row-item-' + activeInspectedId);
        if (card) {
          card.remove();
          triggerToast('Pengajuan ' + studentName + ' ditolak dengan catatan: "' + (notes || 'Perlu perbaikan berkas') + '"', false);
        }
      }
      document.getElementById('verifierNotes').value = '';
    }

    function handleQuickSearch(keyword) {
      const q = keyword.toLowerCase().trim();
      const clearBtn = document.getElementById('clearSearchBtn');
      if (q.length > 0) {
        clearBtn.classList.remove('hidden');
      } else {
        clearBtn.classList.add('hidden');
      }

      document.querySelectorAll('.queue-card').forEach(card => {
        const text = card.innerText.toLowerCase();
        if (text.includes(q)) {
          card.style.display = 'block';
        } else {
          card.style.display = 'none';
        }
      });
    }

    function clearSearch() {
      const input = document.getElementById('queueSearchInput');
      input.value = '';
      handleQuickSearch('');
    }

    function filterCategory(cat, element) {
      document.querySelectorAll('.cat-pill').forEach(btn => {
        btn.classList.remove('bg-pastel-lavender-start', 'text-badge-violet', 'font-bold');
        btn.classList.add('bg-surface-container', 'text-on-surface-variant');
      });
      element.classList.remove('bg-surface-container', 'text-on-surface-variant');
      element.classList.add('bg-pastel-lavender-start', 'text-badge-violet', 'font-bold');

      document.querySelectorAll('.queue-card').forEach(card => {
        const cardCat = card.getAttribute('data-category');
        if (cat === 'all' || cardCat === cat) {
          card.style.display = 'block';
        } else {
          card.style.display = 'none';
        }
      });
    }

    function filterByTab(tab) {
      document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.remove('bg-surface-card', 'text-on-surface', 'shadow-sm', 'font-bold');
        btn.classList.add('text-on-surface-variant');
      });
      const active = document.getElementById('tab-' + tab);
      if (active) {
        active.classList.add('bg-surface-card', 'text-on-surface', 'shadow-sm', 'font-bold');
        active.classList.remove('text-on-surface-variant');
      }
      triggerToast('Beralih ke tab: ' + active.innerText);
    }

    function sortQueue(criteria) {
      const container = document.getElementById('queueListContainer');
      const cards = Array.from(container.getElementsByClassName('queue-card'));
      
      cards.sort((a, b) => {
        if (criteria === 'highest-xp') {
          return parseInt(b.getAttribute('data-xp')) - parseInt(a.getAttribute('data-xp'));
        }
        return 0; // Default order
      });
      
      cards.forEach(card => container.appendChild(card));
      triggerToast('Antrean diurutkan berdasarkan ' + criteria);
    }

    function viewFullDocument() {
      document.getElementById('docViewerModal').classList.remove('hidden');
    }

    function closeDocViewer() {
      document.getElementById('docViewerModal').classList.add('hidden');
    }

    function openNewQuestModal() {
      document.getElementById('newQuestModal').classList.remove('hidden');
    }

    function closeNewQuestModal() {
      document.getElementById('newQuestModal').classList.add('hidden');
    }

    function saveNewQuest() {
      closeNewQuestModal();
      triggerToast('Misi baru berhasil dibuat & dipublikasikan ke mahasiswa!');
    }
  </script>
</div></main></div>



</body></html>